<?php require 'config/config.php';require_role(['accountant']);$page_title='Expenses';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$s=$pdo->prepare('INSERT INTO expenses(category,description,amount,expense_date,payment_method,recorded_by) VALUES(?,?,?,?,?,?)');$s->execute([$_POST['category'],$_POST['description'],$_POST['amount'],$_POST['expense_date'],$_POST['payment_method'],user()['id']]);log_action('Expense recorded',$_POST['description'].' '.money($_POST['amount']));$msg='Expense saved.';}$rows=$pdo->query('SELECT e.*,u.name FROM expenses e JOIN users u ON u.id=e.recorded_by ORDER BY expense_date DESC,id DESC LIMIT 100')->fetchAll();require 'includes/header.php';?><h1>Expenses</h1><?php if($msg):?><div class="alert success"><?=$msg?></div><?php endif;?><div class="panel"><form method="post"><?php csrf_field();?><div class="formgrid"><div><label>Category</label><select name="category"><option>Transport</option><option>Salaries</option><option>Utilities</option><option>Packaging</option><option>Maintenance</option><option>Other</option></select></div><div><label>Description</label><input name="description" required></div><div><label>Amount (RWF)</label><input type="number" min="1" step="1" name="amount" required></div><div><label>Date</label><input type="date" name="expense_date" value="<?=date('Y-m-d')?>"></div><div><label>Payment method</label><select name="payment_method"><option>Cash</option><option>Bank</option><option>Mobile Money</option></select></div></div><p><button>Record expense</button></p></form></div><div class="panel"><h2>Expense history</h2><table><tr><th>Date</th><th>Category</th><th>Description</th><th>Amount</th><th>Method</th><th>Recorded by</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['expense_date'])?></td><td><?=e($r['category'])?></td><td><?=e($r['description'])?></td><td><?=money($r['amount'])?></td><td><?=e($r['payment_method'])?></td><td><?=e($r['name'])?></td></tr><?php endforeach;?></table></div><?php require 'includes/footer.php';?>